/**
 * Naming-convention rules for Concerto model ASTs.
 *
 * The Concerto metamodel serialises a model to JSON where every node carries a
 * `$class` discriminator, for example `concerto.metamodel@1.0.0.ConceptDeclaration`.
 * These rules walk that structure and report identifiers that do not follow the
 * expected casing convention.
 */

/**
 * A single naming-convention violation.
 */
export interface LintViolation {
    /** Stable identifier of the rule that produced the violation. */
    rule: string;
    /** Human readable description of the problem, including the offending name. */
    message: string;
    /** The offending identifier. */
    name: string;
    /** Path to the offending node within the AST (namespace-relative). */
    path: string[];
    /** Severity of the violation. */
    severity: 'error';
}

/** Short `$class` names of the declarations that introduce a named type. */
const TYPE_DECLARATION_CLASSES = new Set([
    'ConceptDeclaration',
    'AssetDeclaration',
    'ParticipantDeclaration',
    'TransactionDeclaration',
    'EventDeclaration',
    'EnumDeclaration',
    'ScalarDeclaration',
]);

const ENUM_DECLARATION_CLASS = 'EnumDeclaration';

/** Matches identifiers whose first character is an upper-case letter. */
const STARTS_WITH_UPPERCASE = /^[A-Z]/;

/** Matches a valid UPPER_SNAKE_CASE constant (e.g. `SOME_VALUE`, `MALE`). */
const UPPER_SNAKE_CASE = /^[A-Z0-9]+(_[A-Z0-9]+)*$/;

/**
 * Extracts the short type name from a fully qualified metamodel `$class`.
 * For example `concerto.metamodel@1.0.0.ConceptDeclaration` -> `ConceptDeclaration`.
 * @param $class the fully qualified `$class` value, may be undefined
 * @returns the short type name, or an empty string when unavailable
 */
function shortClassName($class: unknown): string {
    if (typeof $class !== 'string') {
        return '';
    }
    const lastDot = $class.lastIndexOf('.');
    return lastDot === -1 ? $class : $class.substring(lastDot + 1);
}

/**
 * Applies all naming-convention rules to a parsed Concerto model AST.
 * @param model the parsed metamodel `Model` object
 * @returns the list of naming violations, empty when the model is compliant
 */
export function checkNamingConventions(model: any): LintViolation[] {
    const violations: LintViolation[] = [];

    const declarations: any[] = Array.isArray(model?.declarations)
        ? model.declarations
        : [];

    for (const declaration of declarations) {
        const declarationClass = shortClassName(declaration?.$class);
        const declarationName: unknown = declaration?.name;

        // Rule: type declarations must use camelCase (lower-case first letter).
        if (
            TYPE_DECLARATION_CLASSES.has(declarationClass) &&
            typeof declarationName === 'string' &&
            STARTS_WITH_UPPERCASE.test(declarationName)
        ) {
            violations.push({
                rule: 'type-declaration-camel-case',
                message: `Type declaration "${declarationName}" should use camelCase (start with a lower-case letter).`,
                name: declarationName,
                path: ['declarations', declarationName],
                severity: 'error',
            });
        }

        const properties: any[] = Array.isArray(declaration?.properties)
            ? declaration.properties
            : [];

        if (declarationClass === ENUM_DECLARATION_CLASS) {
            // Rule: enum constants must use UPPER_SNAKE_CASE.
            for (const property of properties) {
                const propertyName: unknown = property?.name;
                if (
                    typeof propertyName === 'string' &&
                    !UPPER_SNAKE_CASE.test(propertyName)
                ) {
                    violations.push({
                        rule: 'enum-constant-upper-snake-case',
                        message: `Enum constant "${propertyName}" should use UPPER_SNAKE_CASE.`,
                        name: propertyName,
                        path: [
                            'declarations',
                            typeof declarationName === 'string' ? declarationName : '',
                            'properties',
                            propertyName,
                        ],
                        severity: 'error',
                    });
                }
            }
        } else {
            // Rule: properties on non-enum types must use PascalCase (upper-case first letter).
            for (const property of properties) {
                const propertyName: unknown = property?.name;
                if (
                    typeof propertyName === 'string' &&
                    !STARTS_WITH_UPPERCASE.test(propertyName)
                ) {
                    violations.push({
                        rule: 'property-pascal-case',
                        message: `Property "${propertyName}" should use PascalCase (start with an upper-case letter).`,
                        name: propertyName,
                        path: [
                            'declarations',
                            typeof declarationName === 'string' ? declarationName : '',
                            'properties',
                            propertyName,
                        ],
                        severity: 'error',
                    });
                }
            }
        }
    }

    return violations;
}
