import { checkNamingConventions, LintViolation } from './rulesets/naming';

export { LintViolation } from './rulesets/naming';

/**
 * Lints a JSON-serialised Concerto model AST, enforcing the model naming
 * conventions:
 *
 * - type declarations (concept, asset, participant, transaction, event, enum,
 *   scalar) must use camelCase;
 * - properties on non-enum types must use PascalCase;
 * - enum constants must use UPPER_SNAKE_CASE.
 *
 * @param ast a JSON string containing a serialised Concerto metamodel `Model`
 * @returns a promise resolving to the list of naming violations; an empty array
 *          is returned when the model has no violations
 * @throws if `ast` is not valid JSON
 */
export async function lintAST(ast: string): Promise<Array<LintViolation>> {
    const model = JSON.parse(ast);
    return checkNamingConventions(model);
}
